/* Types */
/**  What agents may do in a folder (and everything inside it). */
export type Access =
/**  Agents can read and search it, but not change anything. */
"read-only" |
/**  Agents can't see it: it's left out of listings and search, and reading it says "not found". */
"hidden" |
/**  Agents' changes become proposals that the person accepts or rejects in the app. */
"review";

export type ActivityEntry = {
	id: number,
	entity_kind: string,
	entity_id: string,
	occurred_at: string,
	action: string,
	summary: string,
	before: unknown | null,
	after: unknown | null,
};

export type Agent = {
	/**  Lowercase with hyphens (`weekly-review`): the slash command and skill name. */
	name: string,
	/**  The file or folder name, for showing (`Weekly review`). */
	title: string,
	description: string,
	/**  The note, or the skill folder's `SKILL.md`. */
	path: string,
	/**  True for a skill folder (`Agents/X/SKILL.md`). */
	skill_folder: boolean,
	schedule: string | null,
	/**  Event triggers such as `created in Daily/`. */
	on: string[],
	/**  Claude Code model alias; absent lets Claude Code choose its default. */
	model: string | null,
	/**  Folders it may change without review. */
	may_change: string[],
	/**  Whether its runs may use web search and fetch (`web: true`). Off unless the person opts in. */
	web: boolean,
	/**  The body: what the agent does. */
	instructions: string,
};

export type AgentRule = RawRule;

export type AgentRun = {
	id: number,
	agent: string,
	title: string,
	started: number,
	finished: number | null,
	late: boolean,
	/**  Human-readable cause: Manual, a schedule, or an event. */
	trigger?: string | null,
	/**  Note that caused an event run. */
	trigger_path?: string | null,
	/**  Shared by all runs caused by one root event. */
	chain_id?: string | null,
	chain_depth?: number | null,
	/**  Claude model actually requested; absent means Claude Code's default. */
	model?: string | null,
	/**  Process attempts made for this run (one plus automatic retries). */
	attempts?: number,
	status: string,
	answer: string,
	error: string | null,
	proposals: number,
	changes?: string[],
	changed_paths?: string[],
	proposal_ids?: number[],
	/**  Saved answers and tool calls; older runs have no transcript. */
	transcript?: RunTranscript,
};

export type AttachmentLocation = "next-to-note" | "folder";

export type Backlink = {
	source: string,
	line: number,
	/**  The source line containing the link. */
	context: string,
	embed: boolean,
};

export type CalendarRange = {
	from: string,
	to: string,
	events: EventOccurrence[],
	work_sessions: CalendarWorkSession[],
	due_markers: DueMarker[],
	unscheduled_tasks: PlannerTask[],
	workload: DayWorkload[],
};

export type CalendarWorkSession = {
	session: WorkSession,
	task_title: string,
	task_status: TaskStatus,
	epic_id: string | null,
	color: string | null,
};

export type CarryOver = {
	/**  The daily note the tasks came from (`None`: there was none before this day). */
	from: string | null,
	/**  The day's note they went to. */
	to: string,
	/**  How many tasks moved (subtasks included). */
	moved: number,
	/**  True when the day's note was created for them. */
	created: boolean,
};

export type ChatEvent =
/**  The session started (or resumed); `mosaic` says whether Mosaic's tools are connected. */
{ kind: "started"; session_id: string; mosaic: boolean } |
/**  Text from Claude (Markdown). */
{ kind: "text"; text: string } |
/**  Claude uses a tool: a short line for the person, and the note it's about if any. */
{ kind: "tool"; id: string; summary: string; path: string | null;
/**  True for tools that change the vault. */
writes: boolean } |
/**  A tool's outcome: failed, or (in a reviewed folder) became a proposal. */
{ kind: "tool_done"; id: string; error: string | null; review: number | null } |
/**  The answer is complete. */
{ kind: "done"; session_id: string | null; cost_usd: number | null; error: string | null };

export type ClaudeInfo = {
	/**  Where `claude` was found, if it was. */
	path: string | null,
	version: string | null,
};

export type CliInfo = {
	/**  The `mosaic` binary shipped inside the app. */
	path: string | null,
	/**  Where `install_cli` links it (on the user's PATH). */
	link: string,
	installed: boolean,
};

